var e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Un rapido controllo in sola lettura per verificare che la stampante sia pronta a iniziare una stampa.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Ricontrolla`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Controllo in corso...`}},ready:{t:0,b:{t:2,i:[{t:3}],s:`Pronta a stampare`}},notReady:{t:0,b:{t:2,i:[{t:3}],s:`Non pronta a stampare`}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:`La stampante non è raggiungibile`}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Klipper è pronto`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Klipper non è pronto (stato: `},{t:4,k:`state`},{t:3,v:`)`}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Nessuna stampa in corso`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Una stampa è già in esecuzione (`},{t:4,k:`state`},{t:3,v:`)`}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Tutti gli assi sono azzerati`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Assi non azzerati (`},{t:4,k:`axes`},{t:3,v:`); l'avvio di una stampa di solito esegue prima l'azzeramento`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Guida`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Guida al controllo pre-stampa`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Chiudi`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è il controllo pre-stampa?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Una verifica in sola lettura per capire se la stampante è pronta a iniziare: non muove né modifica nulla, si limita a riportare lo stato. I blocchi critici rendono l'esito rosso; gli avvisi informano ma non bloccano.`}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cosa controlla`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Che Klipper sia pronto (non spento o in errore), che non ci sia già una stampa in esecuzione, e se gli assi sono azzerati (a titolo informativo, poiché l'avvio di una stampa di solito esegue prima l'azzeramento).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossario`}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:`Stato di Klipper`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Lo stato proprio di Klipper - 'ready' (pronto) significa che è connesso e inattivo; 'shutdown' (spento) o 'error' (errore) significa che non può stampare finché non viene risolto.`}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:`Azzeramento`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Spostare ogni asse fino al suo endstop affinché la stampante sappia dove si trova la toolhead. La maggior parte delle routine di avvio stampa esegue l'azzeramento automaticamente.`}}}}}}};export{e as default};